const { createContext, useContext, useState } = React;
const ThemeValueContext = createContext(null);
const ThemeActionContext = createContext(null);

function ThemeLabel() {
  const theme = useContext(ThemeValueContext);
  console.log('ThemeLabel 렌더');
  return <p>현재 테마: {theme}</p>;
}
function ThemeButton() {
  const setTheme = useContext(ThemeActionContext);
  console.log('ThemeButton 렌더');
  return <button type="button" onClick={() => setTheme((value) => value === 'light' ? 'dark' : 'light')}>테마 변경</button>;
}

function App() {
  const [theme, setTheme] = useState('light');
  return (
    <ThemeActionContext.Provider value={setTheme}>
      <ThemeValueContext.Provider value={theme}>
        <ThemeLabel />
        <ThemeButton />
      </ThemeValueContext.Provider>
    </ThemeActionContext.Provider>
  );
}

ReactDOM.createRoot(document.querySelector('#root')).render(<App />);

